// V4 fixes missing preference/history keys in earlier builds. Preserve any ambiguous legacy value for manual backup.
try {
 const legacyUndefined = localStorage.getItem('undefined');
 if (legacyUndefined !== null) {
  const legacyParsed = JSON.parse(legacyUndefined);
  if (Array.isArray(legacyParsed) && localStorage.getItem(STORAGE.quizHistory) === null) localStorage.setItem(STORAGE.quizHistory, JSON.stringify(legacyParsed));
  else if (legacyParsed && typeof legacyParsed === 'object' && !Array.isArray(legacyParsed) && localStorage.getItem(STORAGE.prefs) === null && ['theme','fontSize','sessionLimit','dailyNewLimit','v3DailyGoal','v3PracticeSkill'].some(k => Object.prototype.hasOwnProperty.call(legacyParsed,k))) localStorage.setItem(STORAGE.prefs, JSON.stringify(legacyParsed));
 }
} catch(e) { /* Keep legacy data untouched; normal backup/restore remains available. */ }
