const todayKey = () => new Date().toLocaleDateString('sv-SE');
function safeRead(key, fallback){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fallback}catch(e){return fallback}}
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch(e){setStatus('Penyimpanan browser penuh atau tidak tersedia. Ekspor cadangan dan kurangi dataset impor.',true);return false}}
function keyFor(w){return (String(w.japanese||'').trim()+'|'+String(w.hiragana||'').trim()).toLocaleLowerCase()}
function mergeDatasets(seed, extras){const map=new Map(); for(const w of [...seed,...extras]){if(!w||!w.japanese||!w.hiragana)continue;const k=keyFor(w);if(!map.has(k))map.set(k,w)}return [...map.values()]}
function wordProgress(w){return progress[w.id]||{status:'new',interval:0,dueAt:0,repetitions:0,reviewedAt:0}}
function isDue(w){const p=wordProgress(w);return (p.status==='again'||p.status==='mastered')&&Number(p.dueAt||0)<=Date.now()}
function setStatus(msg,error=false){const el=$('importStatus');el.textContent=msg||'';el.className='status'+(error?' error':msg?' success':'')}
function uniqueId(base, used){let x=String(base||'imported');if(!used.has(x)){used.add(x);return x}let n=2;while(used.has(x+'-'+n))n++;x=x+'-'+n;used.add(x);return x}
