function v12RubyMarkup(text){const source=String(text||''),keys=Object.keys(V12_COMMON_FURIGANA).sort((a,b)=>b.length-a.length);let out='';for(let i=0;i<source.length;){const hit=keys.find(k=>source.startsWith(k,i));if(hit){out+=`<ruby>${String(hit).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}<rt>${String(V12_COMMON_FURIGANA[hit]).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]))}</rt></ruby>`;i+=hit.length;}else{const ch=source[i++];out+=ch==='&'?'&amp;':ch==='<'?'&lt;':ch==='>'?'&gt;':ch;}}return out;}
function setAttrs(word){$('japaneseWord').textContent=word.japanese||'Kosakata tidak tersedia';$('readingWord').textContent=word.hiragana||'Bacaan belum tersedia';$('meaningWord').textContent=word.meaning||'Arti belum tersedia';$('posTag').textContent=posLabels[word.partOfSpeech]||word.partOfSpeech||'Belum dikategorikan';$('jlptTag').textContent=word.jlpt||'Unclassified';$('categoryTags').replaceChildren();(word.categories||[]).slice(0,5).forEach(c=>{const s=document.createElement('span');s.className='tag';s.textContent=categoryLabel(c);$('categoryTags').append(s)});
 const hasEx=!!(word.exampleJapanese||word.exampleMeaning);$('exampleArea').classList.toggle('hidden',!hasEx);$('exampleJapanese').innerHTML=v12RubyMarkup(word.exampleJapanese||'');$('exampleMeaning').textContent=word.exampleMeaning||'';
 $('romajiWord').textContent=word.hiragana?toRomaji(word.hiragana):'Romaji belum tersedia';$('romajiWord').classList.toggle('hidden',!$('romajiToggle').checked);
}
function categoryLabel(c){const item=categoryCatalog.find(x=>x[0]===c);return item?item[1]:c}
function renderCard(){if(!filteredWords.length){isBack=false;$('card').classList.remove('is-back');$('card').dataset.face='front';$('card').setAttribute('aria-label','Tidak ada kartu pada hasil filter.');if($('cardFaceStatus'))$('cardFaceStatus').textContent='Tidak ada kartu.';$('japaneseWord').textContent='Tidak ada hasil';$('frontHint').textContent='Ubah kata pencarian atau filter di panel kiri.';$('answerArea').style.display='none';$('readingWord').textContent='';if($('romajiWord'))$('romajiWord').textContent='';$('meaningWord').textContent='';$('positionLabel').textContent='Kartu 0 dari 0';$('cardCountLabel').textContent='Tidak ada kartu dalam filter';$('reviewLabel').textContent='';$('prevBtn').disabled=$('nextBtn').disabled=$('flipBtn').disabled=$('againBtn').disabled=$('masteredBtn').disabled=true;$('sessionTotal').textContent='0 kartu dalam sesi';$('sessionProgress').style.width='0%';return}
 currentIndex=Math.min(Math.max(currentIndex,0),filteredWords.length-1);const w=filteredWords[currentIndex];currentId=w.id;setAttrs(w);$('card').classList.toggle('is-back',isBack);$('answerArea').style.display=isBack?'block':'none';$('frontHint').textContent=isBack?'':'Pikirkan bacaan dan artinya, lalu balik kartu.';$('flipBtn').textContent=isBack?'Sembunyikan jawaban':'Balik kartu';$('positionLabel').textContent=`Kartu ${currentIndex+1} dari ${filteredWords.length}`;$('cardCountLabel').textContent=`ID ${w.id}`;
 const p=wordProgress(w);$('reviewLabel').textContent=p.status==='mastered'?'Status: dikuasai':p.status==='again'?'Status: perlu diulang':p.reviewedAt?'Status: pernah direview':'Belum direview';$('prevBtn').disabled=$('nextBtn').disabled=false;$('flipBtn').disabled=$('againBtn').disabled=$('masteredBtn').disabled=false;$('sessionTotal').textContent=`${filteredWords.length} kartu dalam sesi`;$('sessionProgress').style.width=((currentIndex+1)/filteredWords.length*100)+'%';$('levelLabel').textContent=$('jlptFilter').value==='all'?'Semua tingkat':$('jlptFilter').value;save(STORAGE.session,{id:currentId,index:currentIndex,search:$('search').value,jlpt:$('jlptFilter').value,pos:$('posFilter').value,category:$('categoryFilter').value,study:$('studyFilter').value,order:$('orderMode').value});}
function applyFilters(keepId=null){const q=$('search').value.trim().toLocaleLowerCase();const jlpt=$('jlptFilter').value,pos=$('posFilter').value,cat=$('categoryFilter').value,study=$('studyFilter').value;let arr=allWords.filter(w=>{
 const searchBlob=[w.japanese,w.hiragana,w.meaning,w.partOfSpeech,w.jlpt,...(w.categories||[]),w.exampleJapanese,w.exampleMeaning].join(' ').toLocaleLowerCase();if(q&&!searchBlob.includes(q))return false;if(jlpt!=='all'&&(w.jlpt||'Unclassified')!==jlpt)return false;if(pos!=='all'&&w.partOfSpeech!==pos)return false;if(cat!=='all'&&!(w.categories||[]).includes(cat))return false;const p=wordProgress(w);if(study==='unlearned'&&p.status==='mastered')return false;if(study==='mastered'&&p.status!=='mastered')return false;if(study==='due'&&!isDue(w))return false;if(study==='again'&&p.status!=='again')return false;return true});
 const mode=$('orderMode').value;if(mode==='random'){arr=shuffle(arr)}else if(mode==='dueFirst'){arr.sort((a,b)=>Number(isDue(b))-Number(isDue(a)))}
 filteredWords=arr;if(keepId){const idx=filteredWords.findIndex(w=>w.id===keepId);currentIndex=idx>=0?idx:0}else currentIndex=0;isBack=!practiceMode;renderCard();renderStats();}
function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function move(delta){if(!filteredWords.length)return;currentIndex=(currentIndex+delta+filteredWords.length)%filteredWords.length;isBack=!practiceMode;renderCard()}
function syncCardFace(){
 const card=$('card'),answer=$('answerArea'),status=$('cardFaceStatus'),flipButton=$('flipBtn');
 if(card){card.classList.toggle('is-back',!!isBack);card.dataset.face=isBack?'back':'front';card.setAttribute('aria-label',`Flashcard kosakata${currentId?' '+currentId:''}. Sisi ${isBack?'belakang — jawaban ditampilkan':'depan — jawaban tersembunyi'}. Fokuskan area kartu lalu tekan Enter atau Space untuk membalik.`)}
 if(answer)answer.style.display=isBack?'block':'none';
 if(status)status.textContent=isBack?'Sisi belakang kartu. Jawaban ditampilkan.':'Sisi depan kartu. Jawaban tersembunyi.';
 if(flipButton)flipButton.textContent=isBack?'Sembunyikan jawaban':'Tampilkan jawaban';
}
function flip(){if(!filteredWords.length)return;isBack=!isBack;renderCard()}
function markAgain(){const w=filteredWords[currentIndex];if(!w)return;const old=wordProgress(w);progress[w.id]={...old,status:'again',interval:0,dueAt:Date.now()+10*60*1000,repetitions:Number(old.repetitions||0),reviewedAt:Date.now()};recordDaily();save(STORAGE.progress,progress);applyFilters(w.id);setStatus('Ditandai untuk diulang. Coba lagi setelah sekitar 10 menit.');}
function markMastered(){const w=filteredWords[currentIndex];if(!w)return;const old=wordProgress(w);const reps=Number(old.repetitions||0)+1;const ease=1.8;const interval=old.interval?Math.min(180,Math.max(1,Math.ceil(old.interval*ease))):1;progress[w.id]={...old,status:'mastered',interval,dueAt:Date.now()+interval*86400000,repetitions:reps,reviewedAt:Date.now()};recordDaily();save(STORAGE.progress,progress);applyFilters(w.id);setStatus(`Ditandai dikuasai. Ulangi lagi dalam ${interval} hari.`);}
function recordDaily(){const key=todayKey();daily[key]=Number(daily[key]||0)+1;save(STORAGE.daily,daily)}
function renderStats(){const mastered=allWords.filter(w=>wordProgress(w).status==='mastered').length;const due=allWords.filter(isDue).length;const today=Number(daily[todayKey()]||0);const pct=allWords.length?Math.round(mastered/allWords.length*100):0;$('totalMetric').textContent=allWords.length.toLocaleString('id-ID');$('masteredMetric').textContent=mastered.toLocaleString('id-ID');$('masteredSub').textContent=pct+'% dari dataset';$('dueMetric').textContent=due.toLocaleString('id-ID');$('todayMetric').textContent=today.toLocaleString('id-ID');$('todaySub').textContent='Penilaian kartu hari ini';$('progressSummary').textContent=`${mastered} dari ${allWords.length} kosakata ditandai dikuasai (${pct}%).`; $('masteryProgress').style.width=pct+'%';$('dueSummary').textContent=`${due} kata perlu diulang sekarang atau sudah jatuh tempo. Pengulangan dikuasai memakai interval 1, 2, 4, 8… hari (maksimum 180 hari).`}
function fillCategoryOptions(){const select=$('categoryFilter');const chosen=select.value;const cats=new Map();for(const w of allWords)for(const c of(w.categories||[]))if(!cats.has(c))cats.set(c,categoryLabel(c));for(const [id,label] of categoryCatalog)if(!cats.has(id))cats.set(id,label);select.replaceChildren(new Option('Semua tema','all'));[...cats].sort((a,b)=>a[1].localeCompare(b[1],'id')).forEach(([id,label])=>select.add(new Option(label,id)));select.value=[...select.options].some(o=>o.value===chosen)?chosen:'all'}
function toRomaji(str){const map={'あ':'a','い':'i','う':'u','え':'e','お':'o','か':'ka','き':'ki','く':'ku','け':'ke','こ':'ko','さ':'sa','し':'shi','す':'su','せ':'se','そ':'so','た':'ta','ち':'chi','つ':'tsu','て':'te','と':'to','な':'na','に':'ni','ぬ':'nu','ね':'ne','の':'no','は':'ha','ひ':'hi','ふ':'fu','へ':'he','ほ':'ho','ま':'ma','み':'mi','む':'mu','め':'me','も':'mo','や':'ya','ゆ':'yu','よ':'yo','ら':'ra','り':'ri','る':'ru','れ':'re','ろ':'ro','わ':'wa','を':'wo','ん':'n','が':'ga','ぎ':'gi','ぐ':'gu','げ':'ge','ご':'go','ざ':'za','じ':'ji','ず':'zu','ぜ':'ze','ぞ':'zo','だ':'da','ぢ':'ji','づ':'zu','で':'de','ど':'do','ば':'ba','び':'bi','ぶ':'bu','べ':'be','ぼ':'bo','ぱ':'pa','ぴ':'pi','ぷ':'pu','ぺ':'pe','ぽ':'po','ぁ':'a','ぃ':'i','ぅ':'u','ぇ':'e','ぉ':'o','ゃ':'ya','ゅ':'yu','ょ':'yo'};const combos={'きゃ':'kya','きゅ':'kyu','きょ':'kyo','ぎゃ':'gya','ぎゅ':'gyu','ぎょ':'gyo','しゃ':'sha','しゅ':'shu','しょ':'sho','じゃ':'ja','じゅ':'ju','じょ':'jo','ちゃ':'cha','ちゅ':'chu','ちょ':'cho','ぢゃ':'ja','ぢゅ':'ju','ぢょ':'jo','にゃ':'nya','にゅ':'nyu','にょ':'nyo','ひゃ':'hya','ひゅ':'hyu','ひょ':'hyo','びゃ':'bya','びゅ':'byu','びょ':'byo','ぴゃ':'pya','ぴゅ':'pyu','ぴょ':'pyo','みゃ':'mya','みゅ':'myu','みょ':'myo','りゃ':'rya','りゅ':'ryu','りょ':'ryo'};let s=String(str||'').replace(/[ァ-ヶ]/g,ch=>String.fromCharCode(ch.charCodeAt(0)-0x60)),out='';for(let i=0;i<s.length;i++){const ch=s[i];if(ch==='っ'){const next=s[i+1]||'';const pair=combos[next+(s[i+2]||'')];const roman=pair||map[next]||'';out+=roman?roman[0]:'';continue}if(i+1<s.length&&combos[ch+s[i+1]]){out+=combos[ch+s[i+1]];i++;continue}if(ch==='ー'){out+='-';continue}out+=map[ch]??ch}return out}
