function validateWord(w,i){if(!w||typeof w!=='object'||Array.isArray(w))throw new Error(`Entri ke-${i+1} bukan objek JSON.`);for(const k of ['japanese','hiragana','meaning','partOfSpeech'])if(typeof w[k]!=='string'||!w[k].trim())throw new Error(`Entri ke-${i+1}: kolom “${k}” wajib berupa teks dan tidak boleh kosong.`);if(w.jlpt!=null&&!['N5','N4','N3','N2','N1','Unclassified'].includes(w.jlpt))throw new Error(`Entri ke-${i+1}: level JLPT harus N5–N1 atau Unclassified.`);if(w.categories!=null&&(!Array.isArray(w.categories)||!w.categories.every(c=>typeof c==='string')))throw new Error(`Entri ke-${i+1}: categories harus berupa array teks.`);for(const k of ['exampleJapanese','exampleMeaning'])if(w[k]!=null&&typeof w[k]!=='string')throw new Error(`Entri ke-${i+1}: “${k}” harus berupa teks.`);return true}
async function importDataset(file){if(!file)return;setStatus('Membaca file JSON…');try{const raw=JSON.parse(await file.text());const arr=Array.isArray(raw)?raw:raw&&Array.isArray(raw.words)?raw.words:null;if(!arr)throw new Error('Format tidak dikenali. Gunakan array JSON atau objek dengan properti “words” yang berisi array.');if(!arr.length)throw new Error('Dataset tidak berisi kosakata.');if(arr.length>100000)throw new Error('File terlalu besar: maksimum 100.000 entri per impor.');arr.forEach(validateWord);const existingKeys=new Set(allWords.map(keyFor));const usedIds=new Set(allWords.map(w=>String(w.id)));let addCount=0,dupeCount=0;const clean=[];for(let i=0;i<arr.length;i++){const w=arr[i];const k=keyFor(w);if(existingKeys.has(k)){dupeCount++;continue}existingKeys.add(k);const next={id:uniqueId(w.id||`import-${Date.now()}-${i+1}`,usedIds),japanese:w.japanese.trim(),hiragana:w.hiragana.trim(),meaning:w.meaning.trim(),partOfSpeech:w.partOfSpeech.trim(),jlpt:w.jlpt||'Unclassified',categories:w.categories&&w.categories.length?w.categories.map(c=>c.trim()).filter(Boolean):['impor'],exampleJapanese:w.exampleJapanese||'',exampleMeaning:w.exampleMeaning||''};clean.push(next);addCount++}if(addCount===0)throw new Error(`Tidak ada entri baru. ${dupeCount} kosakata duplikat dilewati.`);const nextImported=mergeDatasets(imported,clean).filter(w=>!SEED.some(s=>keyFor(s)===keyFor(w)));const serialized=JSON.stringify(nextImported);try{localStorage.setItem(STORAGE.imported,serialized)}catch(e){throw new Error('Dataset baru tidak dapat disimpan karena kapasitas localStorage mungkin penuh. Coba impor file yang lebih kecil atau gunakan browser dengan ruang lebih besar. Dataset yang sudah ada tidak dihapus.')};imported=nextImported;allWords=mergeDatasets(SEED,imported);fillCategoryOptions();applyFilters(currentId);setStatus(`Impor selesai: ${addCount} kosakata ditambahkan; ${dupeCount} duplikat dilewati. Total sekarang ${allWords.length}.`)}catch(e){setStatus('Impor gagal: '+(e.message||String(e)),true)}finally{$('importFile').value=''}}
