 setAttrs(w);syncCardFace();$('frontHint').textContent=isBack?'':'Coba ingat bacaan dan arti terlebih dahulu. Jawaban tidak ditampilkan sampai kartu dibalik.';$('positionLabel').textContent=`Kartu ${currentIndex+1} dari ${filteredWords.length}`;$('cardCountLabel').textContent=`${w.japanese} · ${w.id}`;
